import Sidebar from "../components/Sidebar";
import Header from "../components/Header";

export default function DashboardLayout({ children, role }) {
  const sidebarWidth = 240;

  return (
    <div style={{ display: "flex" }}>
     
      <div
        style={{
          width: sidebarWidth,
          position: "fixed",
          top: 0,
          left: 0,
          height: "100vh",
          background: "#1f2937", 
          color: "#fff",
          overflowY: "auto",
        }}
      >
        <Sidebar role={role} />
      </div>

      {/* Main Content */}
      <div
        style={{
          marginLeft: sidebarWidth, 
          flex: 1,
          display: "flex",
          flexDirection: "column",
          minHeight: "100vh",
        }}
      >
        <Header />
        <div
          style={{
            padding: "20px",
            overflowY: "auto", 
            flex: 1,
          }}
        >
          {children}
        </div>
      </div>
    </div>
  );
}
